html:
{%- macro v(value) -%}{{ (value or "") | e }}{%- endmacro -%}
{%- macro day(value) -%}{{ frappe.utils.format_date(value) if value else "" }}{%- endmacro -%}
{%- macro who(user) -%}{{ v(frappe.db.get_value("User", user, "full_name") if user else "") }}{%- endmacro -%}
{%- macro num(value) -%}{{ "{:.1f}".format(value | float) if value else "" }}{%- endmacro -%}
{%- macro person(employee) -%}{{ v(frappe.db.get_value("Employee", employee, "employee_name") if employee else "") }}{%- endmacro -%}
<style>
.lpl-form { font-family: Cambria, Georgia, serif; font-size: 11.5px; color: #000; line-height: 1.45; }
.lpl-form p { margin: 0 0 8px; }
.lpl-form table { width: 100%; border-collapse: collapse; margin: 0 0 12px; }
.lpl-form tr { page-break-inside: avoid; }
.lpl-form th, .lpl-form td { border: 1px solid #000; padding: 4px 6px; vertical-align: top; text-align: left; }
.lpl-form th { background: #f2f2f2; font-weight: bold; }
.lpl-form h3 { font-size: 12.5px; text-align: center; text-transform: uppercase; margin: 8px 0 12px; }
.lpl-form h4 { font-size: 11.5px; font-weight: bold; margin: 12px 0 6px; }
.lpl-form .rule { min-height: 34px; white-space: pre-wrap; border: 1px solid #000; padding: 4px 6px; margin: 0 0 12px; }
.lpl-form .scores td, .lpl-form .scores th { text-align: center; }
.lpl-form .scores td { font-weight: bold; }
.lpl-form .right { text-align: right; }
.lpl-form .muted { color: #444; font-size: 10.5px; }
.lpl-form table.bare { border: none; }
.lpl-form table.bare > tbody > tr > td, .lpl-form table.bare > tr > td { border: none; padding: 0; }
.lpl-form .pre { white-space: pre-wrap; }
.lpl-form .nowrap { white-space: nowrap; }
.lpl-form .grid td, .lpl-form .grid th { text-align: center; vertical-align: middle; height: 30px; }
.lpl-form .grid td { width: 27%; font-size: 10.5px; }
.lpl-form .grid .axis { width: 19%; font-weight: bold; background: #f2f2f2; }
.lpl-form .grid .here { background: #bfbfbf; font-weight: bold; font-size: 11.5px; }
.lpl-form .sign td { border: none; padding: 14px 6px 0 0; width: 33%; }
.lpl-form .sign .line { border-top: 1px solid #000; padding-top: 3px; }
</style>
<div class="lpl-form">
<h3>Graduate Trainee Progress</h3>
<table>
<tr><th style="width:18%">Trainee</th><td>{{ v(doc.trainee_name) }}</td><th style="width:17%">Cohort</th><td>{{ v(doc.cohort) }}</td></tr>
<tr><th>Designation</th><td>{{ v(doc.designation) }}</td><th>Home Department</th><td>{{ v(doc.home_department) }}</td></tr>
<tr><th>Home Plant</th><td>{{ v(doc.home_branch) }}</td><th>Mentor</th><td>{{ v(doc.mentor_name) }}</td></tr>
<tr><th>Programme</th><td>{{ day(doc.start_date) }} to {{ day(doc.end_date) }}</td><th>Stage</th><td><b>{{ v(doc.status) }}</b></td></tr>
<tr><th>Employee Record</th><td>{{ v(doc.employee) }}</td><th>Onboarding</th><td>{{ v(doc.employee_onboarding) }}</td></tr>
</table>

<table class="scores">
<tr><th>Milestones Passed</th><th>Average Score</th><th>Last Result</th><th>Rotations Completed</th></tr>
<tr><td>{{ doc.milestones_passed or 0 }} of {{ doc.milestones | length }}</td><td>{{ num(doc.average_score) }}</td>
<td>{{ v(doc.last_result) }}</td>
<td>{{ doc.rotations | selectattr("completed") | list | length }} of {{ doc.rotations | length }}</td></tr>
</table>

{%- if doc.checklist %}
<h4>Induction</h4>
<table>
<tr><th style="width:4%">#</th><th>Item</th><th style="width:9%">Done</th><th style="width:14%">On</th><th style="width:34%">Remarks</th></tr>
{%- for row in doc.checklist %}
<tr><td>{{ loop.index }}</td><td>{{ v(row.item) }}</td><td>{{ "Yes" if row.done else "No" }}</td><td class="nowrap">{{ day(row.done_on) }}</td>
<td class="pre">{{ v(row.remarks) }}</td></tr>
{%- endfor %}
</table>
{%- endif %}

<h4>Rotations</h4>
<table>
<tr><th style="width:4%">#</th><th style="width:16%">Function and Plant</th><th style="width:13%">Period</th>
<th style="width:14%">Supervisor</th><th>Objectives</th><th>Outcome</th><th style="width:8%">Score</th></tr>
{%- for row in doc.rotations %}
<tr><td>{{ loop.index }}</td><td>{{ v(row.department) }}{% if row.branch %}, {{ v(row.branch) }}{% endif %}</td>
<td class="nowrap">{{ day(row.from_date) }}<br>to {{ day(row.to_date) }}</td><td>{{ person(row.supervisor) }}</td>
<td class="pre">{{ v(row.objectives) }}</td><td class="pre">{{ v(row.outcome) }}{% if row.completed %}<br><span class="muted">Completed</span>{% endif %}</td>
<td class="right">{{ num(row.score) }}</td></tr>
{%- else %}
<tr><td colspan="7">No rotation yet.</td></tr>
{%- endfor %}
</table>

<h4>Milestones</h4>
<table>
<tr><th style="width:4%">#</th><th style="width:20%">Milestone</th><th style="width:11%">Due</th><th style="width:11%">Competency out of 10</th>
<th style="width:10%">Score out of 100</th><th style="width:10%">Result</th><th style="width:14%">Assessed By</th><th>Remarks</th></tr>
{%- for row in doc.milestones %}
<tr><td>{{ loop.index }}</td><td>{{ v(row.milestone) }}{% if row.appraisal %}<br><span class="muted">{{ v(row.appraisal) }}</span>{% endif %}</td>
<td class="nowrap">{{ day(row.due_on) }}</td><td class="right">{{ num(row.competency_check) }}</td><td class="right">{{ num(row.score) }}</td>
<td>{{ v(row.result) }}</td><td>{{ who(row.assessed_by) }}</td><td class="pre">{{ v(row.remarks) }}</td></tr>
{%- else %}
<tr><td colspan="8">No milestone set yet.</td></tr>
{%- endfor %}
</table>

{%- if doc.confirmed_employment_type or doc.placement or doc.succession_position or doc.exit_reason %}
<h4>Outcome</h4>
<table>
{%- if doc.confirmed_employment_type %}<tr><th style="width:26%">Confirmed as</th><td>{{ v(doc.confirmed_employment_type) }}</td></tr>{% endif %}
{%- if doc.placement %}<tr><th style="width:26%">Nine-Box Placement</th><td>{{ v(doc.placement) }}</td></tr>{% endif %}
{%- if doc.succession_position %}<tr><th style="width:26%">Entered the Succession Pool for</th>
<td>{{ v(frappe.db.get_value("Succession Position", doc.succession_position, "designation")) }} ({{ v(doc.succession_position) }})</td></tr>{% endif %}
{%- if doc.exit_reason %}<tr><th style="width:26%">Reason for Exit</th><td>{{ v(doc.exit_reason) }}{% if doc.separation %} ({{ v(doc.separation) }}){% endif %}</td></tr>{% endif %}
</table>
{%- endif %}

<table class="sign"><tr>
<td><div class="line">Inducted by: {{ who(doc.inducted_by) }}</div><span class="muted">Date {{ day(doc.inducted_on) }}</span></td>
<td><div class="line">Mentor: {{ v(doc.mentor_name) }}</div><span class="muted">Sign and date</span></td>
<td><div class="line">Confirmed by: {{ who(doc.confirmed_by) }}</div><span class="muted">Date {{ day(doc.confirmed_on) }}</span></td>
</tr></table>
</div>
